package com.library.service; import com.library.dao.*; import com.library.enums.Role; import com.library.exception.AuthorizationException; import com.library.model.*; import com.library.session.SessionManager; import java.util.*;
public class ReportService { private final BookDAO books=new BookDAO(); private final UserDAO users=new UserDAO(); private final TransactionDAO tx=new TransactionDAO(); private void admin(){if(!SessionManager.hasRole(Role.ADMIN))throw new AuthorizationException("Admin access required.");} public Map<String,Number> statistics(){admin();tx.refreshOverdue();return tx.statistics();} public List<Book> books(String query){admin();return books.findAll(query==null?"":query);} public List<Member> members(){admin();return users.findMembers("");} public List<Transaction> transactions(){admin();tx.refreshOverdue();return tx.findAll("");} }
